use vstd::prelude::*;

verus! {

// Reverse a slice of i32 values into a new vector
fn reverse(a: &[i32]) -> (result: Vec<i32>)
    ensures
        // The result has the same length as the input
        result.len() == a@.len(),
        // Every element in the result is the reverse of the input
        forall|i: int| 0 <= i < a@.len() ==> 
            result[i] == a@[a@.len() - 1 - i],
{
    let mut result: Vec<i32> = Vec::with_capacity(a.len());
    let mut j = 0;
    // index j start from the end of a
    while j < a.len()
        invariant j <= a.len(),
        invariant result.len() == j,
        invariant forall|k: int| 0 <= k < j as int ==>
            result[k] == a[a.len() - 1 - k as usize],
    {
        result.push(a[a.len() - 1 - j]);
        j = j + 1;
    }
    result
}

}